# ---- Terraform: MirrorMaker 2 Kubernetes Deployment ----
# File: terraform/mirrormaker2.tf

resource "kubernetes_config_map" "mm2_config" {
  metadata {
    name      = "mirrormaker2-config"
    namespace = "kafka"
  }
  data = {
    "mm2.properties" = <<-EOT
      # Source and target cluster aliases
      clusters = source, target

      # Source cluster (us-east-1 production)
      source.bootstrap.servers = kafka-prod.us-east-1.internal:9092
      source.security.protocol = SASL_SSL
      source.sasl.mechanism    = PLAIN

      # Target cluster (us-west-2 DR standby)
      target.bootstrap.servers = kafka-dr.us-west-2.internal:9092
      target.security.protocol = SASL_SSL
      target.sasl.mechanism    = PLAIN

      # Replication policy
      source->target.enabled                        = true
      source->target.topics                         = orders, payments, user-events
      source->target.groups                         = etl-consumer-group, analytics-consumer-group
      source->target.emit.heartbeats.enabled        = true
      source->target.emit.checkpoints.enabled       = true
      source->target.sync.group.offsets.enabled     = true
      source->target.sync.group.offsets.interval.seconds = 60

      # Replication factor for replicated topics on target cluster
      replication.factor = 3

      # Do not replicate internal topics
      topics.blacklist = .*\.internal, __consumer_offsets
    EOT
  }
}

resource "kubernetes_deployment" "mirrormaker2" {
  metadata {
    name      = "mirrormaker2"
    namespace = "kafka"
    labels    = { app = "mirrormaker2" }
  }
  spec {
    replicas = 2  # HA: two MM2 workers
    selector { match_labels = { app = "mirrormaker2" } }
    template {
      metadata { labels = { app = "mirrormaker2" } }
      spec {
        container {
          name  = "mirrormaker2"
          image = "confluentinc/cp-kafka:7.5.0"
          command = [
            "/bin/bash", "-c",
            "kafka-mirror-maker.sh --config /etc/mm2/mm2.properties"
          ]
          resources {
            requests = { cpu = "2", memory = "4Gi" }
            limits   = { cpu = "4", memory = "8Gi" }
          }
          volume_mount {
            name       = "mm2-config"
            mount_path = "/etc/mm2"
          }
        }
        volume {
          name = "mm2-config"
          config_map { name = "mirrormaker2-config" }
        }
      }
    }
  }
}

resource "kubernetes_horizontal_pod_autoscaler" "mm2_hpa" {
  metadata { name = "mirrormaker2-hpa"; namespace = "kafka" }
  spec {
    scale_target_ref {
      api_version = "apps/v1"; kind = "Deployment"; name = "mirrormaker2"
    }
    min_replicas = 2
    max_replicas = 6
    metric {
      type = "Resource"
      resource {
        name = "cpu"
        target { type = "Utilization"; average_utilization = 70 }
      }
    }
  }
}
